import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';
import { useEffect, useState } from 'react';
import { FiVolume2, FiVolumeX } from 'react-icons/fi';

// Generated by _archive/perf-patch/optimize-media.sh
const POSTER_640 = '/images/hero/hero-poster-640.webp';
const POSTER_1280 = '/images/hero/hero-poster-1280.webp';
const VIDEO_MOBILE = '/videos/hero-540.mp4';
const VIDEO_DESKTOP = '/videos/hero-720.mp4';
const VIDEO_ORIGINAL = '/videos/hero.mp4'; // fallback if the light versions are missing

const canPlayVideo = () => {
  const c = navigator.connection;
  if (c && (c.saveData || /2g/.test(c.effectiveType || ''))) return false;
  if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) return false;
  return true;
};

export default function HeroVideo() {
  const { t } = useTranslation();
  const [isMuted, setIsMuted] = useState(true);
  const [sources, setSources] = useState(null); // null = poster only
  const [playing, setPlaying] = useState(false);

  const toggleMute = () => {
    setIsMuted(!isMuted);
  };

  // Poster first (it is the LCP image). The video is attached only after the page has
  // loaded and the browser is idle, using a small file on mobile.
  useEffect(() => {
    if (!canPlayVideo()) return undefined;
    const mobile = window.matchMedia('(max-width: 767px)').matches;
    const start = () => setSources([mobile ? VIDEO_MOBILE : VIDEO_DESKTOP, VIDEO_ORIGINAL]);

    let idleId;
    let timer;
    const schedule = () => {
      if ('requestIdleCallback' in window) idleId = window.requestIdleCallback(start, { timeout: 2500 });
      else timer = setTimeout(start, 1500);
    };

    if (document.readyState === 'complete') schedule();
    else window.addEventListener('load', schedule, { once: true });

    return () => {
      window.removeEventListener('load', schedule);
      if (idleId && 'cancelIdleCallback' in window) window.cancelIdleCallback(idleId);
      clearTimeout(timer);
    };
  }, []);

  return (
    <section className="relative w-full">
      {/* ===== ویدیو ===== */}
      <div className="relative w-full h-[40vh] sm:h-[50vh] md:h-[60vh] min-h-[240px] max-h-[560px] overflow-hidden bg-[#0a0a0a]">
        <img
          src={POSTER_1280}
          srcSet={`${POSTER_640} 640w, ${POSTER_1280} 1280w`}
          sizes="100vw"
          alt=""
          fetchPriority="high"
          decoding="async"
          className="absolute inset-0 w-full h-full object-cover"
          onError={(e) => { e.currentTarget.style.display = 'none'; }}
        />

        {sources && (
          <video
            className="absolute inset-0 w-full h-full object-cover"
            style={{ opacity: playing ? 1 : 0, transition: 'opacity 400ms ease' }}
            autoPlay
            loop
            muted={isMuted}
            playsInline
            preload="auto"
            onPlaying={() => setPlaying(true)}
          >
            {sources.map((src) => (
              <source key={src} src={src} type="video/mp4" />
            ))}
          </video>
        )}
        <div className="absolute inset-0 bg-gradient-to-b from-black/20 via-transparent to-black/40" />

        {/* ===== دکمه کنترل صدا ===== */}
        <button
          onClick={toggleMute}
          className="absolute bottom-6 right-6 z-20 p-3 rounded-full bg-black/50 backdrop-blur-sm hover:bg-black/70 transition-all duration-300 text-white border border-white/20"
          aria-label={isMuted ? 'فعال کردن صدا' : 'قطع کردن صدا'}
        >
          {isMuted ? <FiVolumeX size={20} /> : <FiVolume2 size={20} />}
        </button>
      </div>

      {/* ===== محتوا — زیر ویدیو، یک ردیف ===== */}
      <div className="relative z-10 bg-gradient-to-r from-[#FFF8F0] via-white to-[#FFF8F0] px-4 sm:px-8 py-5 sm:py-6 md:py-8 border-y border-[#FFD700]/20">
        <div
          dir="rtl"
          className="max-w-7xl mx-auto flex flex-wrap items-center justify-center gap-3 sm:gap-4 md:gap-6"
        >
          {/* عنوان — قرمز + مشکی */}
          <h1 className="text-xl sm:text-2xl md:text-3xl lg:text-4xl xl:text-5xl font-black leading-tight shrink-0">
            <span className="text-[#DC2626]">Authentic</span>{' '}
            <span className="text-[#1A1A1A]">Iranian</span>{' '}
            <span className="text-[#DC2626]">Taste</span>
            <span className="sr-only"> - Kabab Dagh Nan Dagh, Iranian restaurant in Doha, Qatar</span>
          </h1>

          {/* دکمه View Menu */}
          <Link
            to="/menu"
            className="shrink-0 inline-block px-5 sm:px-8 md:px-10 lg:px-12 py-2.5 sm:py-3 md:py-4 bg-gradient-to-r from-[#FFD700] to-[#F9A825] hover:from-[#F9A825] hover:to-[#FFD700] text-black font-black text-sm sm:text-base md:text-lg rounded-full transition-all duration-300 shadow-lg shadow-[#FFD700]/30 hover:shadow-xl hover:shadow-[#FFD700]/50 hover:scale-105 active:scale-95 border-2 border-white/30 whitespace-nowrap"
          >
            {t('hero.cta')}
          </Link>

          {/* زیرنویس */}
          <p className="text-sm sm:text-base md:text-lg lg:text-xl xl:text-2xl font-semibold text-[#4A4A4A] leading-relaxed shrink-0">
            {t('hero.subtitle')}
          </p>
        </div>
      </div>
    </section>
  );
}
